css:
body :where([data-bz-node="lc"]) .bz-block{padding:0}
body :where([data-bz-node="lc"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="lc"]>.bz-container{padding-inline:0}

body [data-bz-node="lc"]{background:#fff;padding:100px 0 100px}
body [data-bz-node="lc"]>.bz-container{max-width:var(--container)}
body [data-bz-node="lc-top"]{display:grid;grid-template-columns:1fr 296px;gap:0 56px;align-items:start}
body [data-bz-node="lc-left"],body [data-bz-node="lc-right"]{grid-column:auto}
body [data-bz-node="lc-head"] .bz-eyebrow{font:700 11px/1.4 var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:#6b6b6a;margin:0 0 6px;margin-bottom:7px}
body [data-bz-node="lc-head"] h2{font:700 42.4px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="lc-intro"] .bz-text{max-width:420px;margin-top:16px}
body [data-bz-node="lc-intro"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node="lc-depts"]{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:21px}
body [data-bz-node="lc-depts-label"],body [data-bz-node^="lc-dept-"]{grid-column:auto}
body [data-bz-node="lc-depts-label"]{margin-right:12px}
body [data-bz-node="lc-depts-label"] p{font:700 11px/1 var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node^="lc-dept-"] p{display:flex;align-items:center;justify-content:center;height:42px;padding:0 14px;border:1px solid #d0d0ce;font:700 10.5px/1 var(--font-body);letter-spacing:.15em;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="lc-cov-label"] p{font:700 11px/1.4 var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:#6b6b6a;margin:12px 0 24px}
body [data-bz-node="lc-areas"]{display:block}
body [data-bz-node^="lc-area-"]{grid-column:auto;display:block;padding:0}
body [data-bz-node^="lc-area-"] h3{font:700 23px/41.2px var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;border-bottom:2px solid transparent}
body [data-bz-node^="lc-area-"]:first-child h3{border-bottom-color:var(--ink)}
body [data-bz-node="lc-bottom"]{display:grid;grid-template-columns:390px 1fr;gap:16px;margin:47px 1px 0;align-items:stretch}
body [data-bz-node="lc-card"],body [data-bz-node="lc-photo"]{grid-column:auto}
body [data-bz-node="lc-card"]{position:relative;border:1px solid #d4d4d2;background:#fff;padding:24px 24px 23px;display:flex;flex-direction:column;box-sizing:border-box;min-height:300px}
body [data-bz-node="lc-name"] h3{font:700 22px/35px var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;max-width:260px}
body [data-bz-node="lc-tag"]{position:absolute;top:61px;right:24px}
body [data-bz-node="lc-tag"] p{font:700 11px/1 var(--font-body);letter-spacing:.15em;color:#555;margin:0}
body [data-bz-node="lc-addr"]{margin-top:21px}
body [data-bz-node="lc-addr"] p{font:400 12.5px/21px var(--font-body);color:#555;margin:0}
body [data-bz-node="lc-phones"]{margin-top:6px}
body [data-bz-node="lc-phones"] p{font:400 12.5px/20px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node="lc-phones"] a,body [data-bz-node="lc-email"] a{color:inherit}
body [data-bz-node="lc-email"]{margin-top:6px}
body [data-bz-node="lc-email"] p{font:400 12.5px/20px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node="lc-actions"]{margin-top:auto}
body [data-bz-node="lc-actions"] .bz-btns{margin:0;gap:21px}
body [data-bz-node="lc-actions"] .bz-btn{padding:0 0 0 26px;border:0;background:none;color:var(--ink);font:500 12.5px/18px var(--font-body);text-decoration:none;position:relative;height:18px}
body [data-bz-node="lc-actions"] .bz-btn::before{content:"";position:absolute;left:2px;top:0;width:16px;height:16px;background:var(--ink);-webkit-mask:url(/icons/directions.svg) center/16px no-repeat;mask:url(/icons/directions.svg) center/16px no-repeat}
body [data-bz-node="lc-actions"] .bz-btn:nth-child(2)::before{-webkit-mask-image:url(/icons/mail.svg);mask-image:url(/icons/mail.svg)}
body [data-bz-node="lc-actions"] .bz-btn:hover{color:var(--accent)}
body [data-bz-node="lc-photo"]{position:relative;min-height:300px;border:1px solid #d4d4d2;box-sizing:border-box}
body [data-bz-node="lc-photo"] .bz-block,body [data-bz-node="lc-photo"] .bz-container,body [data-bz-node="lc-photo"] figure{height:100%;margin:0}
body [data-bz-node="lc-photo"] img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:0}
@media (max-width:1100px){
  body [data-bz-node="lc"]{padding:72px 24px}
  body [data-bz-node="lc-head"] h2{font-size:34px}
  body [data-bz-node="lc-top"]{grid-template-columns:1fr;gap:36px}
  body [data-bz-node="lc-bottom"]{grid-template-columns:1fr;margin-top:48px}
  body [data-bz-node="lc-photo"]{min-height:0;aspect-ratio:16/9}
}
@media (max-width:640px){
  body [data-bz-node="lc"]{padding:56px 20px}
  body [data-bz-node="lc-head"] h2{font-size:28px}
  body [data-bz-node^="lc-area-"] h3{font-size:19px;line-height:38px}
  body [data-bz-node="lc-depts-label"]{flex:0 0 100%}
  body [data-bz-node="lc-card"]{padding:20px}
  body [data-bz-node="lc-tag"]{top:20px;right:20px}
  body [data-bz-node="lc-name"] h3{font-size:19px;line-height:30px;max-width:220px}
}
